test("ceiling rounds 25 units of case size 12 to 3 cases and 36 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("raises an order that rounds to fewer than 2 cases up to 2 cases", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 5, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("does not round an exact multiple at the 2 case limit any further", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("raises an order of exactly 1 case to 2 cases", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 12, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("raises an order one unit below 1 case to 2 cases", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 11, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("ceilings one unit above 1 case to 2 cases and does not increase it", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 13, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("ceilings one unit below exact 2 cases to 2 cases", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 23, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test("raises a 1 unit order with case size 8 to 2 cases and 16 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 1, caseSize: 8 }), { cases: 2, shippedUnits: 16 });
});

test("raises a 1 unit order with case size 1 to 2 cases and 2 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 1, caseSize: 1 }), { cases: 2, shippedUnits: 2 });
});

test("raises an exact 1 case order when case size is 3.0 to 2 cases and 6 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 3, caseSize: 3.0 }), { cases: 2, shippedUnits: 6 });
});

test("ceilings one unit above exact 2 cases with case size 6 to 3 cases and 18 units", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 13, caseSize: 6 }), { cases: 3, shippedUnits: 18 });
});

test("ceilings an exact halfway quotient up rather than to half even", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 30, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("ceilings the closest order below halfway to the next whole case", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 29, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("ceilings the closest order above halfway to the next whole case", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 31, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test("ceilings the closest order below a halfway the unit step cannot hit", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 17, caseSize: 5 }), { cases: 4, shippedUnits: 20 });
});

test("does not add an extra case for an exact multiple above the minimum", function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 15, caseSize: 5 }), { cases: 3, shippedUnits: 15 });
});
